  @override
  String formatNumber(double value) {
    return value == value.toInt() ? value.toInt().toString() : value.toString();
  }

  @override
  String formatDateTime(
    DateTime dateTime, {
    bool showDate = true,
    bool showSeconds = false,
    bool showTime = true,
    bool use24HourFormat = true,
  }) {
    var result = '';
    if (showDate) {
      result += '${dateTime.year}年${dateTime.month}月${dateTime.day}日';
    }
    if (showTime) {
      if (result.isNotEmpty) {
        result += ' ';
      }
      result += _formatClock(
        hour: dateTime.hour,
        minute: dateTime.minute,
        second: dateTime.second,
        showSeconds: showSeconds,
        use24HourFormat: use24HourFormat,
      );
    }

    return result;
  }

  @override
  String formatMonthYear(int month, int year) => '$year年$month月';

  @override
  String formatTimeOfDay(
    TimeOfDay time, {
    bool showSeconds = false,
    bool use24HourFormat = true,
  }) {
    return _formatClock(
      hour: time.hour,
      minute: time.minute,
      second: time.second,
      showSeconds: showSeconds,
      use24HourFormat: use24HourFormat,
    );
  }

  // Digits and the AM/PM split come from `CoreClockFormat` so every
  // locale on both platforms agrees on noon, midnight and padding; this
  // locale only decides where its period word sits.
  String _formatClock({
    required int hour,
    required int minute,
    required int second,
    required bool showSeconds,
    required bool use24HourFormat,
  }) {
    final digits = CoreClockFormat.digits(
      hour: hour,
      minute: minute,
      second: second,
      showSeconds: showSeconds,
      use24HourFormat: use24HourFormat,
    );
    if (use24HourFormat) {
      return digits;
    }
    final period = CoreClockFormat.isPm(hour) ? timePM : timeAM;

    return '$period$digits';
  }

  @override
  String formatDuration(
    Duration duration, {
    bool showDays = true,
    bool showHours = true,
    bool showMinutes = true,
    bool showSeconds = true,
  }) {
    final days = duration.inDays;
    final hours = duration.inHours % Duration.hoursPerDay;
    final minutes = duration.inMinutes % Duration.minutesPerHour;
    final seconds = duration.inSeconds % Duration.secondsPerMinute;
    final parts = <String>[];
    if (showDays && days > 0) {
      parts.add('$days日');
    }
    if (showHours && hours > 0) {
      parts.add('$hours時間');
    }
    if (showMinutes && minutes > 0) {
      parts.add('$minutes分');
    }
    if (showSeconds && seconds > 0) {
      parts.add('$seconds秒');
    }

    return parts.join(' ');
  }

  // Derived from the order of the date placeholders in format.dateTime.
  @override
  List<DatePart> get datePartsOrder => const [
    DatePart.year,
    DatePart.month,
    DatePart.day,
  ];
}
